/* Generated from spatial.astrale-theme.json. Consumer-owned after installation. */
:root,
[data-ui-preset='spatial'],
[data-ui-theme='spatial'] {
  color-scheme: light;
  --ui-background: oklch(0.952 0.003 258);
  --ui-foreground: oklch(0.18 0.013 258);
  --ui-card: oklch(0.995 0.0015 258);
  --ui-card-foreground: oklch(0.18 0.013 258);
  --ui-popover: oklch(0.995 0.0015 258);
  --ui-popover-foreground: oklch(0.18 0.013 258);
  --ui-primary: oklch(0.43 0.17 262);
  --ui-primary-foreground: oklch(0.985 0.002 258);
  --ui-secondary: oklch(0.93 0.004 258);
  --ui-secondary-foreground: oklch(0.18 0.013 258);
  --ui-muted: oklch(0.94 0.004 258);
  --ui-muted-foreground: oklch(0.45 0.014 258);
  --ui-accent: oklch(0.92 0.006 258);
  --ui-accent-foreground: oklch(0.18 0.013 258);
  --ui-destructive: oklch(0.5 0.17 28);
  --ui-destructive-foreground: oklch(0.985 0 0);
  --ui-success: oklch(0.48 0.13 155);
  --ui-success-foreground: oklch(0.985 0 0);
  --ui-info: oklch(0.48 0.15 262);
  --ui-info-foreground: oklch(0.985 0 0);
  --ui-warning: oklch(0.49 0.15 70);
  --ui-warning-foreground: oklch(0.985 0 0);
  --ui-border: oklch(0.875 0.005 258);
  --ui-input: oklch(0.8 0.007 258);
  --ui-ring: oklch(0.55 0.16 262);
  --ui-chart-1: oklch(0.52 0.17 262);
  --ui-chart-2: oklch(0.6 0.11 190);
  --ui-chart-3: oklch(0.7 0.14 75);
  --ui-chart-4: oklch(0.58 0.17 28);
  --ui-chart-5: oklch(0.54 0.14 310);
  --ui-sidebar: oklch(0.974 0.0022 258);
  --ui-sidebar-foreground: oklch(0.18 0.013 258);
  --ui-sidebar-primary: oklch(0.43 0.17 262);
  --ui-sidebar-primary-foreground: oklch(0.985 0.002 258);
  --ui-sidebar-accent: oklch(0.92 0.006 258);
  --ui-sidebar-accent-foreground: oklch(0.18 0.013 258);
  --ui-sidebar-border: oklch(0.875 0.005 258);
  --ui-sidebar-ring: oklch(0.55 0.16 262);
  --ui-radius: 0.625rem;
  --ui-radius-panel: 1rem;
  --ui-radius-action: 9999px;
  --ui-control-height: 2.25rem;
  --ui-control-height-sm: 2rem;
  --ui-control-height-lg: 2.75rem;
  --ui-control-padding: 0.875rem;
  --ui-panel-spacing: 1.25rem;
  --ui-font-body: 'Hanken Grotesk', 'Hanken Grotesk Variable', ui-sans-serif, system-ui, sans-serif;
  --ui-font-heading: 'Hanken Grotesk', 'Hanken Grotesk Variable', ui-sans-serif, system-ui, sans-serif;
  --ui-font-mono: 'SFMono-Regular', 'Cascadia Code', ui-monospace, monospace;
  --ui-tracking-body: 0;
  --ui-tracking-heading: -0.015em;
  --ui-leading-body: 1.5;
  --ui-leading-heading: 1.2;
  --ui-weight-body: 450;
  --ui-weight-heading: 600;
  --ui-weight-label: 550;
  --ui-shadow-control:
    inset 0 1px 0 oklch(1 0 0 / 0.8), 1px 1px 2px -1px oklch(0.22 0.025 258 / 0.08);
  --ui-shadow-panel:
    inset 0 1px 0 oklch(1 0 0), 1px 2px 4px -2px oklch(0.22 0.025 258 / 0.08), 6px 18px 40px -20px oklch(0.22 0.025 258 / 0.18);
  --ui-shadow-overlay:
    inset 0 1px 0 oklch(1 0 0), 2px 4px 8px -3px oklch(0.22 0.025 258 / 0.1), 12px 32px 64px -28px oklch(0.22 0.025 258 / 0.28);
  --ui-backdrop: oklch(0.2 0.01 258 / 0.32);
  --ui-motion-fast: 120ms;
  --ui-motion-standard: 180ms;
}

:root.dark,
[data-ui-preset='spatial'].dark,
[data-ui-theme='spatial'].dark {
  color-scheme: dark;
  --ui-background: oklch(0.19 0.006 258);
  --ui-foreground: oklch(0.945 0.004 258);
  --ui-card: oklch(0.235 0.007 258);
  --ui-card-foreground: oklch(0.945 0.004 258);
  --ui-popover: oklch(0.25 0.008 258);
  --ui-popover-foreground: oklch(0.945 0.004 258);
  --ui-primary: oklch(0.76 0.115 262);
  --ui-primary-foreground: oklch(0.19 0.02 262);
  --ui-secondary: oklch(0.25 0.007 258);
  --ui-secondary-foreground: oklch(0.945 0.004 258);
  --ui-muted: oklch(0.25 0.007 258);
  --ui-muted-foreground: oklch(0.73 0.01 258);
  --ui-accent: oklch(0.29 0.01 258);
  --ui-accent-foreground: oklch(0.945 0.004 258);
  --ui-destructive: oklch(0.76 0.13 28);
  --ui-destructive-foreground: oklch(0.19 0.006 258);
  --ui-success: oklch(0.76 0.12 155);
  --ui-success-foreground: oklch(0.15 0.02 255);
  --ui-info: oklch(0.76 0.115 262);
  --ui-info-foreground: oklch(0.15 0.02 255);
  --ui-warning: oklch(0.82 0.13 75);
  --ui-warning-foreground: oklch(0.15 0.02 255);
  --ui-border: oklch(0.31 0.008 258);
  --ui-input: oklch(0.4 0.01 258);
  --ui-ring: oklch(0.7 0.13 262);
  --ui-chart-1: oklch(0.7 0.13 262);
  --ui-chart-2: oklch(0.72 0.1 190);
  --ui-chart-3: oklch(0.8 0.13 75);
  --ui-chart-4: oklch(0.72 0.14 28);
  --ui-chart-5: oklch(0.7 0.12 310);
  --ui-sidebar: oklch(0.215 0.007 258);
  --ui-sidebar-foreground: oklch(0.945 0.004 258);
  --ui-sidebar-primary: oklch(0.76 0.115 262);
  --ui-sidebar-primary-foreground: oklch(0.19 0.02 262);
  --ui-sidebar-accent: oklch(0.27 0.01 258);
  --ui-sidebar-accent-foreground: oklch(0.945 0.004 258);
  --ui-sidebar-border: oklch(0.31 0.008 258);
  --ui-sidebar-ring: oklch(0.7 0.13 262);
  --ui-shadow-control:
    inset 0 1px 0 oklch(1 0 0 / 0.04), 0 1px 2px oklch(0 0 0 / 0.3);
  --ui-shadow-panel:
    inset 0 1px 0 oklch(1 0 0 / 0.05), 6px 18px 40px -20px oklch(0 0 0 / 0.5);
  --ui-shadow-overlay:
    inset 0 1px 0 oklch(1 0 0 / 0.06), 12px 32px 64px -28px oklch(0 0 0 / 0.65);
  --ui-backdrop: oklch(0 0 0 / 0.5);
}
